let body = $input.first().json.body || $input.first().json;
if (body && typeof body === 'object') {
  const bodyKeys = Object.keys(body);
  const jsonKey = bodyKeys.find(k => k.startsWith('{'));
  if (jsonKey) {
    const raw = Object.entries(body).map(([k, v]) => k + '=' + v).join('&');
    try { body = JSON.parse(raw); } catch (e) {
      const extract = (field) => { const re = new RegExp('"' + field + '":"([^"]*)"'); const m = raw.match(re); return m ? m[1] : ''; };
      body = { account_id: extract('account_id'), user_provider_id: extract('user_provider_id'), user_full_name: extract('user_full_name'), user_public_identifier: extract('user_public_identifier'), user_profile_url: extract('user_profile_url') };
    }
  }
}
const data = body.data || body.object || body;
let accountId = body.account_id || data.account_id || '';
const providerId = String(data.user_provider_id || data.provider_id || data.id || '');
let name = data.user_full_name || data.name || data.display_name || '';
const publicId = data.user_public_identifier || data.public_identifier || '';
let profileUrl = data.user_profile_url || data.public_profile_url || data.profile_url || '';
if (!profileUrl && publicId) profileUrl = 'https://www.linkedin.com/in/' + publicId;
if (!profileUrl && providerId) profileUrl = 'https://www.linkedin.com/in/' + providerId;
let prenom = '';
if (name) prenom = name.split(/\s+/)[0] || '';
if (prenom) prenom = prenom.charAt(0).toUpperCase() + prenom.slice(1).toLowerCase();
if (!accountId) accountId = '6oH8b0a4QK2d9u9QOiL4Sg';
if (!providerId) throw new Error('Donnees webhook incompletes: providerId manquant');
return [{ json: { accountId, providerId, name, prenom, publicId, profileUrl } }];

const providerId = $('Extract Contact Info').first().json.providerId;
const accountId = $('Extract Contact Info').first().json.accountId;
let cursor = null;
let hasMessages = false;
let pages = 0;
do {
  const url = 'https://YOUR_UNIPILE_DSN/api/v1/chats?account_id=' + accountId + '&limit=100' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : '');
  const resp = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'X-API-KEY': 'YOUR_UNIPILE_API_KEY' }, json: true });
  const chats = resp.items || [];
  for (const chat of chats) {
    const attendeeId = String(chat.attendee_provider_id || '');
    if (attendeeId === providerId) { hasMessages = true; break; }
    const attendees = chat.attendees || [];
    for (const a of attendees) { if (String(a.provider_id || '') === providerId) { hasMessages = true; break; } }
    if (hasMessages) break;
  }
  cursor = resp.cursor || null;
  pages++;
} while (cursor && !hasMessages && pages < 20);
return [{ json: { ...$('Extract Contact Info').first().json, shouldContinue: !hasMessages } }];

const resp = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.github.com/repos/Martenous2000/mon-setter-bot/contents/prompts/personas/florian.md',
  headers: { 'Authorization': 'token YOUR_GITHUB_TOKEN', 'Accept': 'application/vnd.github.v3.raw', 'User-Agent': 'n8n-florian-workflow' },
});
const personaMd = typeof resp === 'string' ? resp : (resp.toString ? resp.toString() : JSON.stringify(resp));
const resp2 = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.github.com/repos/Martenous2000/mon-setter-bot/contents/prompts/icebreakers-regles-strictes.md',
  headers: { 'Authorization': 'token YOUR_GITHUB_TOKEN', 'Accept': 'application/vnd.github.v3.raw', 'User-Agent': 'n8n-florian-workflow' },
});
const reglesMd = typeof resp2 === 'string' ? resp2 : (resp2.toString ? resp2.toString() : JSON.stringify(resp2));
return [{ json: { ...$input.first().json, personaMd, reglesMd } }];

const contactData = $('Extract Contact Info').first().json;
const profile = $('Scrape Profile (Unipile)').first().json || {};
const personaMd = $input.first().json.personaMd || '';
const reglesMd = $input.first().json.reglesMd || '';
const prenom = contactData.prenom || '';
const providerId = contactData.providerId;
const profileUrl = contactData.profileUrl || '';
const headline = profile.headline || '';
const name = contactData.name || '';

let posts = [];
try {
  const raw = $('Scrape Posts (Unipile)').first().json;
  posts = raw.items || raw.posts || (Array.isArray(raw) ? raw : []);
  if (!Array.isArray(posts)) posts = [];
} catch(e) { posts = []; }

// Type 1 only, no freshness window per règles strictes: pick first post with real text, prefer event/complaint/opinion style but any works.
const usablePosts = posts.filter(p => (p.text || p.content || '').trim().length > 20).slice(0, 3);
const hasPosts = usablePosts.length > 0;

let userContent;
if (hasPosts) {
  const postsText = usablePosts.map((p, i) => 'Post ' + (i+1) + ': ' + (p.text || p.content || '').substring(0, 600)).join('\n\n');
  userContent = 'Prenom du lead : ' + prenom + '\nCeci fait suite a l\'acceptation de sa demande de connexion.\nDerniers posts LinkedIn disponibles (choisis le plus adapte a une reaction sincere) :\n' + postsText;
} else {
  userContent = 'Prenom du lead : ' + prenom + '\nCeci fait suite a l\'acceptation de sa demande de connexion.\nAUCUN post trouve pour ce profil malgre une recherche sur 10 posts recents. Headline: ' + (headline || '(vide)') + '\nRemonte ce cas (pas de Type 2), redige un message d\'ouverture minimal respectant quand meme le format Type 1 general (Helllo, aucune formule generique, tutoiement) base sur la headline en dernier recours.';
}

const systemPrompt = 'Tu es Mathias Chow sur LinkedIn. Voici ton persona complet (ICP, positionnement) :\n\n' + personaMd + '\n\nVoici les regles strictes obligatoires pour rediger un icebreaker (Type 1 uniquement, format exact, interdits) :\n\n' + reglesMd + '\n\nApplique ces regles A LA LETTRE : format "Helllo [prenom]" en debut de message, 2-3 lignes maximum, jamais de Type 2, jamais de formule generique type "merci pour la connexion" ou "j\'espere que tu vas bien", tutoiement, 1 emoji maximum (jamais 😄, prefere 😉 si besoin), jamais de tiret cadratin, jamais de guillemets autour du message final, question courte et specifique en fin de message qui rebondit sur le post.\n\nReponds UNIQUEMENT avec le message final, sans guillemets autour, rien d\'autre.';

let icebreaker = '';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { 'Authorization': 'Bearer YOUR_OPENROUTER_API_KEY', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'anthropic/claude-opus-4', messages: [ { role: 'system', content: systemPrompt }, { role: 'user', content: userContent } ], temperature: 0.5, max_tokens: 150 }),
    json: true,
  });
  icebreaker = (resp.choices[0].message.content || '').trim();
  if ((icebreaker.startsWith('"') && icebreaker.endsWith('"'))) icebreaker = icebreaker.slice(1, -1);
} catch(e) {
  icebreaker = 'Helllo ' + prenom + ', je viens de voir ton profil, ca me parle bien ce que tu fais. Tu te concentres sur quoi en ce moment';
}

return [{ json: { accountId: contactData.accountId, providerId, prenom, headline, profileUrl, icebreaker, hasPosts, name } }];

